 const build=JSON.parse(read(OUT+'/workbench-'+idx+'-build-proof.json')),candidate=read(OUT+build.url),patches=JSON.parse(read(OUT+'/workbench-'+idx+'-patches.json'));
 assert.equal(sha(candidate),build.sha256);assert(inputs.some(x=>'/'+x.relative===build.url&&x.sha256===build.sha256));
 let inverse=candidate;for(const p of [...patches].reverse()){assert.equal(candidate.slice(p.afterStart,p.afterEnd),p.after);inverse=inverse.slice(0,p.afterStart)+p.before+inverse.slice(p.afterEnd)}
