 assert.equal(declaration(beforeAst,'__d51_rx_chat_helpers_get'),declaration(afterAst,'__d51_rx_chat_helpers_get'),'original chat helpers byte-identical');
 assert.equal(build.allPriorChatCodeUnchanged,true);patchSets.push(ui.after);proofs.push({url:build.url,sha256:build.sha256,inverse:true,chatDataNoticeAndHelpersByteIdentical:true});
